// n8n Code node — formats Apify Upwork job results into an HTML digest email.
// Input: items from the Apify output (each item's `json` is one job, or the
//        first item's `json` is the full array — handles both shapes).
// Input: new job_ids from Postgres RETURNING; full
//job data from 'Aggregate Job Ids' node. 

 // Get new job IDs from Postgres RETURNING output
  const newJobIds = new Set($input.all().map(i => i.json.job_id));

  // Get full job objects from the aggregate node
  const allJobs = $('Aggregate Job Ids').first().json.allJobs;

  // Filter to only new jobs
  let jobs = allJobs.filter(job => newJobIds.has(String(job.uid)));

  if (jobs.length === 0) return [];

// ── Helpers ────────────────────────────────────────────────────────────────

function formatBudget(budget) {
  if (!budget) return 'Not specified';
  if (budget.fixedBudget && budget.fixedBudget > 0) {
    return `$${budget.fixedBudget.toLocaleString()} fixed`;
  }
  if (budget.hourlyRate) {
    const { min, max } = budget.hourlyRate;
    if (min && max) return `$${min}–$${max}/hr`;
    if (min) return `$${min}+/hr`;
  }
  return 'Not specified';
}

function formatDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric',
  });
}

function truncate(text, maxLen = 300) {
  if (!text || text.length <= maxLen) return text ?? '';
  return text.slice(0, maxLen).replace(/\s+\S*$/, '') + '…';
}

function scoreColor(score) {
  if (score >= 4.5) return '#16a34a'; // green
  if (score >= 3.5) return '#d97706'; // amber
  return '#dc2626';                   // red
}

function clientTrust(client) {
  const tags = [];
  if (client.paymentMethodVerified) tags.push('✓ Payment verified');
  if (client.stats?.totalSpent > 0) {
    tags.push(`$${(client.stats.totalSpent / 1000).toFixed(0)}k spent`);
  }
  if (client.stats?.totalHires > 0) tags.push(`${client.stats.totalHires} hires`);
  if (client.stats?.hireRate > 0)    tags.push(`${client.stats.hireRate}% hire rate`);
  if (client.stats?.feedbackRate > 0) {
    tags.push(`★ ${client.stats.feedbackRate.toFixed(1)} (${client.stats.feedbackCount})`);
  }
  if (client.countryCode) tags.push(`🌍 ${client.countryCode}`);
  return tags;
}

// ── CSS ────────────────────────────────────────────────────────────────────

const css = `
  body { margin:0; padding:0; background:#f1f5f9; font-family:'Helvetica Neue',Arial,sans-serif; }
  .wrapper { max-width:680px; margin:32px auto; background:#fff; border-radius:12px;
             box-shadow:0 2px 8px rgba(0,0,0,.08); overflow:hidden; }
  .header { background:#14532d; padding:28px 32px; }
  .header h1 { margin:0; color:#fff; font-size:22px; font-weight:700; }
  .header p  { margin:6px 0 0; color:#bbf7d0; font-size:13px; }
  .jobs { padding:24px 32px; }
