// ── Per-job card ───────────────────────────────────────────────────────────

function jobCard(job) {
  const budget   = formatBudget(job.budget);
  const posted   = formatDate(job.publishedAt);
  const score    = job.customJobScore ?? 0;
  const allSkills = job.skills ?? [];
  const skillText = allSkills.length
    ? allSkills.slice(0, 5).join(', ') + (allSkills.length > 5 ? ` +${allSkills.length - 5} more` : '')
    : '';
  const connects = job.applicationCost ? `${job.applicationCost} connects` : '';
  const trust    = clientTrust(job.client ?? {});
  const expLevel = job.vendor?.experienceLevel
    ? job.vendor.experienceLevel.charAt(0) + job.vendor.experienceLevel.slice(1).toLowerCase()
    : '';

  const metaTags = [
    budget       ? `<span class="tag green">${budget}</span>` : '',
    job.category ? `<span class="tag">${job.category}</span>` : '',
    expLevel     ? `<span class="tag">${expLevel}</span>` : '',
    connects     ? `<span class="tag">${connects}</span>` : '',
    posted       ? `<span class="tag">Posted ${posted}</span>` : '',
  ].filter(Boolean).join('');

  const trustHtml = trust.map(t => `<span class="client-tag">${t}</span>`).join('');

  return `
    <div class="job">
      <div class="job-header">
        <p class="job-title">${job.title}</p>
        <span class="score-badge" style="background:${scoreColor(score)}">
          Score ${score.toFixed(1)}
        </span>
      </div>
      <div class="meta">${metaTags}</div>
      ${skillText ? `<p style="margin:4px 0 8px;font-size:12px;color:#64748b;">${skillText}</p>` : ''}
      <p class="description">${truncate(job.description)}</p>
      ${trustHtml ? `<div class="client-tags">${trustHtml}</div>` : ''}
      <a href="${job.externalLink}" class="apply-btn">View Job →</a>
    </div>
  `;
}

// ── Assemble email ─────────────────────────────────────────────────────────

const today     = new Date().toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric', year:'numeric' });
const jobCards  = jobs.map(jobCard).join('');
const jobCount  = jobs.length;

const htmlBody = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Upwork Job Digest</title>
  <style>${css}</style>
</head>
<body>
  <div class="wrapper">
    <div class="header">
      <h1>Upwork Job Digest</h1>
      <p>${jobCount} new job${jobCount !== 1 ? 's' : ''} matched · ${today}</p>
    </div>
    <div class="jobs">
      ${jobCards}
    </div>
    <div class="footer">
      <p>Sourced automatically via Apify · Unsubscribe anytime</p>
    </div>
  </div>
</body>
</html>`;

// Plain-text fallback
const textBody = jobs.map((job, i) => {
  const budget = formatBudget(job.budget);
  const posted = formatDate(job.publishedAt);
  const score  = (job.customJobScore ?? 0).toFixed(1);
  const lines  = [
    `${i + 1}. ${job.title}`,
    `   Score: ${score}  |  Budget: ${budget}  |  Posted: ${posted}`,
    job.category ? `   Category: ${job.category}` : '',
    job.vendor?.experienceLevel ? `   Level: ${job.vendor.experienceLevel}` : '',
    job.applicationCost ? `   Connects: ${job.applicationCost}` : '',
    (job.skills ?? []).length ? `   Skills: ${job.skills.join(', ')}` : '',
    '',
    truncate(job.description, 200),
    '',
    `   Apply: ${job.externalLink}`,
    '-'.repeat(60),
  ];
  return lines.filter(l => l !== null).join('\n');
}).join('\n\n');

// ── Output (compatible with n8n Email node) ────────────────────────────────

return [{
  json: {
    subject:  `Upwork Digest: ${jobCount} new job${jobCount !== 1 ? 's' : ''} · ${today}`,
    htmlBody,
    textBody,
    jobCount,
  },
}];

// Same new-jobs filter as 'Format Email', reused so we only post prospects
// that weren't already seen in a prior run (dedupe already happened at the
// Postgres RETURNING step upstream).
const newJobIds = new Set($input.all().map(i => i.json.job_id));
const allJobs = $('Aggregate Job Ids').first().json.allJobs;
const jobs = allJobs.filter(job => newJobIds.has(String(job.uid)));

return jobs.map(job => ({
  json: {
    source: 'upwork',
    source_external_id: String(job.uid),
    name: job.title,
    website: job.externalLink,
    summary: job.description,
    raw_payload: job
  }
}));
